#!/usr/bin/env dotnet
using System; using System.Collections.Generic; using System.Threading.Tasks; using Microsoft.Extensions.DependencyInjection; using Microsoft.Extensions.Options; using Microsoft.Extensions.Logging; using Milvus.Client; using System.Buffers; using System.Threading.Channels; using System.Threading; using System.Diagnostics; using OpenTelemetry.Trace; using OpenTelemetry.Metrics; using OpenTelemetry.Resources; using Polly; using System.Linq;  namespace MilvusIntegration {     public class MilvusOptions     {         public string Host { get; set; } = "localhost";         public int Port { get; set; } = 19530;         public string CollectionName { get; set; } = "default_collection";         public int Dimension { get; set; } = 128;         public int MaxConnections { get; set; } = 10;         public TimeSpan ConnectionTimeout { get; set; } = TimeSpan.FromSeconds(30);         public bool EnableAOT { get; set; } = false;         public bool UseMemoryPool { get; set; } = true;         public int BatchSize { get; set; } = 1000;         public bool EnableDistributedTracing { get; set; } = true;         public bool EnableMetrics { get; set; } = true;         public int MaxRetryAttempts { get; set; } = 3;         public TimeSpan RetryDelay { get; set; } = TimeSpan.FromSeconds(1);         public string ServiceName { get; set; } = "MilvusService";     }      public interface IMilvusService     {         Task CreateCollectionAsync(string collectionName, int dimension);         Task InsertVectorsAsync(string collectionName, IEnumerable<float[]> vectors, IEnumerable<long> ids);         Task BatchInsertVectorsAsync(string collectionName, IEnumerable<IEnumerable<float[]>> vectorBatches, IEnumerable<IEnumerable<long>> idBatches);         Task<IEnumerable<(long Id, float Distance)>> SearchAsync(string collectionName, float[] queryVector, int topK);         Task OptimizePerformanceAsync();         Task EnableAOTCompilationAsync();         Task UseMemoryPoolingAsync();         Task EnableDistributedTracingAsync();         Task EnableMetricsCollectionAsync();         Task ConfigureRetryPolicyAsync();     }      public class MilvusService : IMilvusService     {         private readonly MilvusClient _client;         private readonly ILogger<MilvusService> _logger;         private readonly MemoryPool<float> _memoryPool;         private readonly Channel<MilvusClient> _clientPool;         private readonly MilvusOptions _options;         private readonly ActivitySource _activitySource;         private readonly Meter _meter;         private readonly IAsyncPolicy _retryPolicy;          public MilvusService(IOptions<MilvusOptions> options, ILogger<MilvusService> logger, MemoryPool<float> memoryPool)         {             _options = options.Value;             _logger = logger;             _memoryPool = memoryPool;                          // Initialize client pool             _clientPool = Channel.CreateBounded<MilvusClient>(_options.MaxConnections);             for (int i = 0; i < _options.MaxConnections; i++)             {                 _clientPool.Writer.TryWrite(new MilvusClient(_options.Host, _options.Port));             }              // Initialize distributed tracing             _activitySource = new ActivitySource(_options.ServiceName);                          // Initialize metrics             _meter = new Meter(_options.ServiceName);                          // Configure retry policy             _retryPolicy = Policy                 .Handle<Exception>()                 .WaitAndRetryAsync(                     _options.MaxRetryAttempts,                      retryAttempt => _options.RetryDelay,                     (exception, delay, retryCount, context) =>                      {                         _logger.LogWarning(exception, $"Retry {retryCount} after {delay.TotalSeconds} seconds");                     });         }          public async Task CreateCollectionAsync(string collectionName, int dimension)         {             using var client = await GetClientAsync();             await client.CreateCollectionAsync(collectionName, dimension);         }          public async Task InsertVectorsAsync(string collectionName, IEnumerable<float[]> vectors, IEnumerable<long> ids)         {             using var activity = _activitySource.StartActivity("InsertVectors");             using var client = await GetClientAsync();                          await _retryPolicy.ExecuteAsync(async () =>              {                 var counter = _meter.CreateCounter<int>("milvus_insert_operations", "count", "Number of insert operations");                 counter.Add(1);                                  await client.InsertAsync(collectionName, vectors, ids);             });         }                  public async Task BatchInsertVectorsAsync(string collectionName, IEnumerable<IEnumerable<float[]>> vectorBatches, IEnumerable<IEnumerable<long>> idBatches)         {             using var activity = _activitySource.StartActivity("BatchInsertVectors");             using var client = await GetClientAsync();                          var batchTasks = vectorBatches.Zip(idBatches, (vectors, ids) =>                  _retryPolicy.ExecuteAsync(async () =>                  {                     var counter = _meter.CreateCounter<int>("milvus_batch_insert_operations", "count", "Number of batch insert operations");                     counter.Add(1);                                          await client.InsertAsync(collectionName, vectors, ids);                 }));                              await Task.WhenAll(batchTasks);         }          public async Task<IEnumerable<(long Id, float Distance)>> SearchAsync(string collectionName, float[] queryVector, int topK)         {             using var activity = _activitySource.StartActivity("SearchVectors");             using var client = await GetClientAsync();                          return await _retryPolicy.ExecuteAsync(async () =>              {                 var counter = _meter.CreateCounter<int>("milvus_search_operations", "count", "Number of search operations");                 counter.Add(1);                                  var histogram = _meter.CreateHistogram<float>("milvus_search_latency", "milliseconds", "Search operation latency");                 var stopwatch = Stopwatch.StartNew();                                  try                 {                     var result = await client.SearchAsync(collectionName, queryVector, topK);                     return result;                 }                 finally                 {                     stopwatch.Stop();                     histogram.Record(stopwatch.ElapsedMilliseconds);                 }             });         }          public async Task OptimizePerformanceAsync()         {             using var activity = _activitySource.StartActivity("OptimizePerformance");                          // Performance optimization logic             await Task.CompletedTask;         }          public async Task EnableAOTCompilationAsync()         {             using var activity = _activitySource.StartActivity("EnableAOTCompilation");                          // AOT compilation logic             await Task.CompletedTask;         }          public async Task UseMemoryPoolingAsync()         {             using var activity = _activitySource.StartActivity("UseMemoryPooling");                          // Memory pooling logic             await Task.CompletedTask;         }                  public async Task EnableDistributedTracingAsync()         {             // Distributed tracing configuration             await Task.CompletedTask;         }                  public async Task EnableMetricsCollectionAsync()         {             // Metrics collection configuration             await Task.CompletedTask;         }                  public async Task ConfigureRetryPolicyAsync()         {             // Retry policy configuration             await Task.CompletedTask;         }          private async ValueTask<MilvusClient> GetClientAsync()         {             return await _clientPool.Reader.ReadAsync();         }          private async ValueTask ReturnClientAsync(MilvusClient client)         {             await _clientPool.Writer.WriteAsync(client);         }     }      public static class ServiceCollectionExtensions     {         public static IServiceCollection AddMilvus(this IServiceCollection services, Action<MilvusOptions> configure)         {             services.Configure(configure);             services.AddSingleton<MemoryPool<float>>(sp => MemoryPool<float>.Shared);                          // Add OpenTelemetry for distributed tracing and metrics             services.AddOpenTelemetry()                 .WithTracing(tracing => tracing                     .AddSource("MilvusService")                     .AddAspNetCoreInstrumentation()                     .AddConsoleExporter())                 .WithMetrics(metrics => metrics                     .AddMeter("MilvusService")                     .AddAspNetCoreInstrumentation()                     .AddConsoleExporter());                                  services.AddSingleton<IMilvusService, MilvusService>();             return services;         }     }      public static class ApplicationBuilderExtensions     {         public static IApplicationBuilder UseMilvus(this IApplicationBuilder app)         {             return app;         }     }      public static class ExampleUsage     {         public static async Task Demo()         {             var services = new ServiceCollection();             services.AddMilvus(options =>             {                 options.Host = "localhost";                 options.Port = 19530;                 options.CollectionName = "test_collection";                 options.Dimension = 128;                 options.MaxConnections = 10;             });              var provider = services.BuildServiceProvider();             var milvusService = provider.GetRequiredService<IMilvusService>();              await milvusService.CreateCollectionAsync("test_collection", 128);              var vectors = new List<float[]>();             var ids = new List<long>();             for (int i = 0; i < 1000; i++)             {                 var vector = new float[128];                 for (int j = 0; j < 128; j++) vector[j] = Random.Shared.NextSingle();                 vectors.Add(vector);                 ids.Add(i);             }              await milvusService.InsertVectorsAsync("test_collection", vectors, ids);              var queryVector = new float[128];             for (int j = 0; j < 128; j++) queryVector[j] = Random.Shared.NextSingle();              var results = await milvusService.SearchAsync("test_collection", queryVector, 10);             foreach (var result in results)             {                 Console.WriteLine($"ID: {result.Id}, Distance: {result.Distance}");             }         }     } }
